from pathlib import Path
import json,xml.etree.ElementTree as ET,html,shutil
out=Path('Worldbuilding/归档/2026-10-05_敌人推进与移动流光');files=['Worldbuilding/策划案/OCC_项目总策划案_v1.0.md','Worldbuilding/数据表/OCC_美术与界面规格表_v1.0.csv','Tools/OCCArt/occ_art_contract_v1.json','UnityProject/Assets/Game/Runtime/Combat/EnemyArchetypes.cs','UnityProject/Assets/Game/Runtime/Presentation/FormalBattlefieldView.cs','UnityProject/Assets/Game/Tests/EditMode/EnemyPackTests.cs']
for f in files:shutil.copy2(f,out/'backup'/Path(f).name)
xml=ET.fromstring(json.loads((out/'cloud-A17.json').read_text(encoding='utf-8-sig'))['data']['document']['content']);p=next(p for p in xml.iter('p') if ''.join(p.itertext()).startswith('敌人移动意图使用'))
old=''.join(p.itertext());new=old.replace('敌人移动意图使用橙色路径节点与落点框，落点中心保留橙色方向标记；图形由原生32格整数像素几何绘制，保持在地形物件和单位之下。','敌人移动意图保留橙色落点框与中心方向标记；从敌人脚下沿公开的真实移动路径连线至目标格，拐角按实际逐格路线转折，不穿墙、不绘制不可达线路。连线使用暗橙底线与琥珀色细芯，连续亮色能量节段沿敌人到落点的方向涌动，转弯时沿整条路径的累计距离接续；关闭动画时保留稳定连线与方向箭头。图形由原生32格整数像素几何绘制，保持在地形物件和单位之下，不拦截点击；意图改动即更新线路，死亡、重开、离开战斗和停用视图时清理。')
m=Path(files[0]);text=m.read_text(encoding='utf-8-sig');assert text.count(old)==1;m.write_text(text.replace(old,new),encoding='utf-8');(out/'move-route.xml').write_text('<p>'+html.escape(new)+'</p>',encoding='utf-8');(out/'block-id.txt').write_text(p.get('id'),encoding='utf-8')
sp=Path(files[1]);lines=sp.read_text(encoding='utf-8-sig').splitlines();lines=[('ART-ENEMY-DESTINATION,战场,敌人移动连线与落点,从敌人脚下沿真实逐格路径连到橙色落点框；暗橙底线与琥珀细芯；能量节段持续朝落点涌动并沿累计路程过拐角,原生32格像素几何；层级在物件与单位之下；保留落点方向标记,关闭动画保留静态线与箭头；仅可达真实意图；不接收点击；改意图即时更新；死亡退出重开停用清理；意图变化仍850ms暖色反馈' if line.startswith('ART-ENEMY-DESTINATION,') else line) for line in lines];sp.write_text('\n'.join(lines)+'\n',encoding='utf-8')
p=Path(files[2]);c=json.loads(p.read_text(encoding='utf-8-sig'));c['enemy_movement_route']={'source':'CombatEnemyMoveRouteGraphic','geometry':'native32 axis-aligned line from foot anchor through real planned route to destination; dark orange 3px base, amber 1px core','motion':'directional energy packets every 20 native pixels at 48 native pixels/sec using cumulative path length; 15Hz mesh updates','disabled_animation':'stable line and arrow; no moving packets','ownership':'presentation only, no raycast, below terrain objects and units; routes replaced from current public plans','cleanup':'death, no move plan, battle restart/exit and view disable'};p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Prepared block',p)
